#!/usr/bin/env python3
"""Process all artifacts and determine which option contains the first unrecoverable flaw."""

import json
import re
from pathlib import Path

# Read manifest
with open('/input_artifacts/artifact_manifest.json') as f:
    manifest = json.load(f)

artifact_meta = {item['artifact_id']: item for item in manifest}

artifacts_dir = Path('/input_artifacts/artifacts')

def extract_reviewer_note(content):
    """Extract the reviewer note from artifact content."""
    match = re.search(r'## Reviewer Note\s*\n\s*\n(.+)', content, re.DOTALL)
    if match:
        return match.group(1).strip()
    return None

def extract_options(content):
    """Extract the four candidate option texts."""
    options = {}
    for opt in ['A', 'B', 'C', 'D']:
        pattern = rf'### Option {opt}\s*\n\s*```text\s*\n(.*?)\n\s*```'
        match = re.search(pattern, content, re.DOTALL)
        if match:
            options[opt] = match.group(1).strip()
    return options

def extract_full_proof(content):
    """Extract the full candidate proof."""
    match = re.search(r'## Full Candidate Proof\s*\n\s*```text\s*\n(.*?)\n\s*```', content, re.DOTALL)
    if match:
        return match.group(1).strip()
    return None

def find_option_in_proof(option_text, proof_text):
    """Find where an option text appears in the full proof."""
    # Normalize whitespace for comparison
    normalized_option = ' '.join(option_text.split())
    normalized_proof = ' '.join(proof_text.split())

    # Try exact match first
    if option_text in proof_text:
        return proof_text.find(option_text)

    # Try normalized match
    if normalized_option in normalized_proof:
        return 0  # Found but position approximate

    # Try matching first 50 chars
    first_part = option_text[:50].strip()
    if first_part in proof_text:
        return proof_text.find(first_part)

    return None

def determine_flaw_option(artifact_id, content, meta):
    """Determine which option contains the first unrecoverable flaw."""
    reviewer_note = extract_reviewer_note(content)
    options = extract_options(content)
    proof = extract_full_proof(content)

    print(f"\n=== {artifact_id} ===")
    print(f"Note: {reviewer_note}")
    print(f"Meta: {meta['problem_id']}, Competition: {meta['competition']}, Year: {meta['year']}")

    # Map option positions in proof
    option_positions = {}
    for opt, text in options.items():
        pos = find_option_in_proof(text, proof)
        if pos is not None:
            option_positions[opt] = pos
            print(f"  Option {opt}: found at position {pos}")
        else:
            print(f"  Option {opt}: NOT FOUND (first 50 chars: {text[:50]}...)")

    # Based on the reviewer note, determine which option has the flaw
    # This requires careful analysis of the note content

    return reviewer_note, options

# Process all artifacts
for item in sorted(manifest, key=lambda x: x['artifact_id']):
    aid = item['artifact_id']
    filepath = artifacts_dir / f"{aid}.md"
    if filepath.exists():
        content = filepath.read_text()
        determine_flaw_option(aid, content, item)
    else:
        print(f"Missing: {filepath}")

